  `)
}

// ─── Pool Price Command ───────────────────────────────────────────────────────

export async function poolPrice(args) {
  if (!args[0] || !args[1]) {
    console.log(`
Usage:
  pool:price <tokenA> <tokenB>    Show implied price from each DEX

Examples:
  node index.js pool:price wcBTC USDC.e
  node index.js pool:price JUSD wcBTC
  node index.js pool:price ctUSD USDC.e
    `)
    return
  }

  const tokenA = resolveToken(args[0])
  const tokenB = resolveToken(args[1])

  if (!tokenA) { console.log(`❌ Unknown token "${args[0]}"`); return }
  if (!tokenB) { console.log(`❌ Unknown token "${args[1]}"`); return }

  console.log(`\n🔍 Fetching pool prices for ${tokenA.symbol} / ${tokenB.symbol}...`)

  const rows     = []
  const feeTiers = [500, 3000, 10000]

  const queryA = getPoolQueryAddress(tokenA.address)
  const queryB = getPoolQueryAddress(tokenB.address)

  // JuiceSwap pools
  for (const fee of feeTiers) {
    try {
      const poolAddr = await client.readContract({
        address: JUICESWAP_FACTORY,
        abi: UNIV3_FACTORY_ABI,
        functionName: 'getPool',
        args: [queryA, queryB, fee],
      })
      if (poolAddr === '0x0000000000000000000000000000000000000000') continue

      const [slot0, feeRaw] = await Promise.all([
        client.readContract({ address: poolAddr, abi: SLOT0_ABI, functionName: 'slot0' }),
        client.readContract({ address: poolAddr, abi: SLOT0_ABI, functionName: 'fee'   }),
      ])

      const result = computeDisplayPrice(slot0[0], tokenA, tokenB, queryA, queryB)
      if (!result) continue // skip badly initialized pools

      rows.push({
        dex:          'JuiceSwap',
        fee:          `${(Number(feeRaw) / 10000).toFixed(2)}%`,
        pool:         poolAddr,
        ...result,
      })
    } catch {}
  }

  // Satsuma pool
  try {
    const poolAddr = await client.readContract({
      address: SATSUMA_FACTORY,
      abi: ALGEBRA_FACTORY_ABI,
      functionName: 'poolByPair',
      args: [tokenA.address, tokenB.address],
    })
    if (poolAddr !== '0x0000000000000000000000000000000000000000') {
      const state = await client.readContract({
        address: poolAddr,
        abi: GLOBAL_STATE_ABI,
        functionName: 'globalState',
      })

      const result = computeDisplayPrice(state[0], tokenA, tokenB, tokenA.address, tokenB.address)
      if (result) {
        rows.push({
          dex:  'Satsuma',
          fee:  `${(Number(state[2]) / 10000).toFixed(2)}%`,
          pool: poolAddr,
          ...result,
        })
      }
    }
  } catch {}

  if (rows.length === 0) {
    console.log(`⚠️  No valid pools found for ${tokenA.symbol} / ${tokenB.symbol}\n`)
    return
  }

  const prices = await fetchRedStonePrices()

  console.log(`
💱 ${tokenA.symbol} / ${tokenB.symbol} Pool Prices
━━━━━━━━━━━━━━━━━━━━━━━━`)

  for (const row of rows) {
    const oraclePrice = getOraclePrice(row.baseSymbol, prices)
    const deviation   = oraclePrice
      ? ` (${((row.displayPrice - oraclePrice) / oraclePrice * 100).toFixed(3)}% vs oracle)`
      : ''
    console.log(`   ${row.dex.padEnd(10)} ${row.fee.padEnd(8)}  1 ${row.baseSymbol} = ${formatPrice(row.displayPrice, row.quoteSymbol)}${deviation}`)
    console.log(`   Pool: ${row.pool}`)
    console.log()
  }

  const oraclePrice = getOraclePrice(rows[0].baseSymbol, prices)
  if (oraclePrice) {
    console.log(`   Oracle price:  1 ${rows[0].baseSymbol} = ${formatUSD(oraclePrice)} (RedStone)`)
  }
  console.log(`━━━━━━━━━━━━━━━━━━━━━━━━`)
  console.log()
}

import 'dotenv/config'
import { createPublicClient, http, formatUnits } from 'viem'

const citrea = {
  id: 4114,
  name: 'Citrea Mainnet',
  nativeCurrency: { name: 'Citrea Bitcoin', symbol: 'cBTC', decimals: 18 },
  rpcUrls: { default: { http: ['https://rpc.mainnet.citrea.xyz'] } },
  blockExplorers: {
    default: {
      name: 'Citrea Explorer',
      url: 'https://explorer.mainnet.citrea.xyz'
    }
  }
}

const client = createPublicClient({ chain: citrea, transport: http() })

// Router addresses to watch
const ROUTERS = {
  '0x1b9d3E8020Be83C0f2b9eDe6CC6E26C9F2C4Ee2a': 'JuiceSwap',
  '0x3012E9049d05B4B5369D690114D5A5861EbB85cb': 'Satsuma',
}

const TOKEN_MAP = {
  '0x8d82c4e3c936c7b5724a382a9c5a4e6eb7ab6d5d': { symbol: 'ctUSD',  decimals: 18 },
  '0x3100000000000000000000000000000000000006': { symbol: 'wcBTC',  decimals: 18 },
  '0xe045e6c36cf77faa2cfb54466d71a3aef7bbe839': { symbol: 'USDC.e', decimals: 6  },
  '0x9f3096bac87e7f03dc09b0b416eb0df837304dc4': { symbol: 'USDT.e', decimals: 6  },
  '0xdf240dc08b0fdad1d93b74d5048871232f6bea3d': { symbol: 'WBTC.e', decimals: 8  },
  '0x0987d3720d38847ac6dbb9d025b9de892a3ca35c': { symbol: 'JUSD',   decimals: 18 },
}

// ERC20 Transfer event
const TRANSFER_ABI = [{
  name: 'Transfer',
  type: 'event',
  inputs: [
    { name: 'from',  type: 'address', indexed: true  },
    { name: 'to',    type: 'address', indexed: true  },
    { name: 'value', type: 'uint256', indexed: false },
  ],
}]

const CHUNK_SIZE = 1000

function shortAddr(addr) {
  return `${addr.slice(0, 6)}...${addr.slice(-4)}`
}

function formatAmount(value, decimals, symbol) {
  const n = Number(formatUnits(value, decimals))
  if (n < 0.0001)  return `${n.toFixed(8)} ${symbol}`
  if (n < 1)       return `${n.toFixed(6)} ${symbol}`
  if (n < 1000)    return `${n.toFixed(4)} ${symbol}`
  return `${n.toLocaleString('en-US', { maximumFractionDigits: 2 })} ${symbol}`
}

export async function txHistory(args) {
  if (!args[0]) {
    console.log(`
Usage:
  txns <address> [hours]    Show recent swap activity for a wallet

Examples:
  node index.js txns 0xYourAddress
  node index.js txns 0xYourAddress 24
  node index.js txns 0xYourAddress 168
    `)
    return
  }

  const address  = args[0].toLowerCase()
  const hours    = parseInt(args[1] || '24', 10)
  const lookback = BigInt(Math.floor((hours * 3600) / 2)) // Citrea ~2s blocks

  console.log(`\n🔍 Fetching transactions for ${shortAddr(address)} (last ${hours}h)...`)

  const latest    = await client.getBlockNumber()
  const fromBlock = latest - lookback > 0n ? latest - lookback : 0n

  // Fetch Transfer events involving this address across all known tokens
  const tokenAddresses = Object.keys(TOKEN_MAP)
  const allTransfers   = []

  for (let start = fromBlock; start <= latest; start += BigInt(CHUNK_SIZE)) {
    const end = start + BigInt(CHUNK_SIZE) - 1n < latest ? start + BigInt(CHUNK_SIZE) - 1n : latest

    const logs = await Promise.all(
      tokenAddresses.map(tokenAddr =>
        client.getLogs({
          address:   tokenAddr,
          event:     TRANSFER_ABI[0],
          fromBlock: start,
          toBlock:   end,
        }).catch(() => [])
      )
    )

    for (const tokenLogs of logs) {
      for (const log of tokenLogs) {
        const from = log.args.from?.toLowerCase()
        const to   = log.args.to?.toLowerCase()
        if (from === address || to === address) {
          allTransfers.push(log)
        }
      }
    }
  }

  if (allTransfers.length === 0) {
    console.log(`\n✅ No token transfers found for this address in the last ${hours}h.\n`)
    return
  }

  // Group by transaction hash
  const byTx = new Map()
  for (const log of allTransfers) {
    const hash = log.transactionHash
    if (!byTx.has(hash)) byTx.set(hash, [])
    byTx.get(hash).push(log)
  }

  console.log(`\n📋 Found ${byTx.size} transaction(s) in the last ${hours}h:\n`)
  console.log(`━━━━━━━━━━━━━━━━━━━━━━━━`)

  // Fetch block timestamps for ordering
  const blockNums  = [...new Set(allTransfers.map(l => l.blockNumber))]
  const blockTimes = new Map()
  for (const bn of blockNums) {
    try {
      const block = await client.getBlock({ blockNumber: bn })
      blockTimes.set(bn, Number(block.timestamp))
    } catch {}
  }

  // Sort by block descending (newest first)
  const sortedTxs = [...byTx.entries()].sort((a, b) => {
    const blockA = a[1][0].blockNumber
    const blockB = b[1][0].blockNumber
    return blockA > blockB ? -1 : 1
  })

  for (const [hash, logs] of sortedTxs) {
    const blockNum = logs[0].blockNumber
    const ts       = blockTimes.get(blockNum)
    const timeStr  = ts ? new Date(ts * 1000).toLocaleString() : 'unknown time'
    const router   = ROUTERS[logs[0].address] || null

    console.log(`\n🔗 ${hash}`)
    console.log(`   Block:  ${blockNum}  |  ${timeStr}`)
    if (router) console.log(`   DEX:    ${router}`)

    for (const log of logs) {
      const token  = TOKEN_MAP[log.address.toLowerCase()]
      if (!token) continue
      const from   = log.args.from?.toLowerCase()
      const to     = log.args.to?.toLowerCase()
      const dir    = from === address ? '📤 Sent    ' : '📥 Received'
      const amount = formatAmount(log.args.value, token.decimals, token.symbol)
      const counterparty = from === address ? shortAddr(to) : shortAddr(from)
      console.log(`   ${dir}  ${amount.padEnd(28)}  ${from === address ? 'to' : 'from'} ${counterparty}`)
    }

    console.log(`   Explorer: https://explorer.mainnet.citrea.xyz/tx/${hash}`)
  }

  console.log(`\n━━━━━━━━━━━━━━━━━━━━━━━━\n`)
}

import { createPublicClient, http } from 'viem'

// ─── Citrea Mainnet Config ────────────────────────────────────────────────────
const citrea = {
  id: 4114,
  name: 'Citrea Mainnet',
  nativeCurrency: { name: 'Citrea Bitcoin', symbol: 'cBTC', decimals: 18 },
  rpcUrls: { default: { http: ['https://rpc.mainnet.citrea.xyz'] } },
  blockExplorers: {
    default: {
      name: 'Citrea Explorer',
      url: 'https://explorer.mainnet.citrea.xyz'
    }
  }
}

// ─── RedStone Push Feed Contracts on Citrea ───────────────────────────────────
const PRICE_FEEDS = {
  BTC:  '0xc555c100DB24dF36D406243642C169CC5A937f09',
  USDC: '0xf0DEbDAE819b354D076b0D162e399BE013A856d3',
  USDT: '0x4aF6b78d92432D32E3a635E824d3A541866f7a78',
}

const AGGREGATOR_ABI = [
  {
    name: 'latestRoundData',
    type: 'function',
    stateMutability: 'view',
    inputs: [],
    outputs: [
      { name: 'roundId',         type: 'uint80'  },
      { name: 'answer',          type: 'int256'  },
      { name: 'startedAt',       type: 'uint256' },
      { name: 'updatedAt',       type: 'uint256' },
      { name: 'answeredInRound', type: 'uint80'  },
    ],
  },
  {
    name: 'decimals',
    type: 'function',
    stateMutability: 'view',
    inputs: [],
    outputs: [{ name: '', type: 'uint8' }],
  },
]

// Token → feed mapping
// null  = stablecoin, hardcoded to $1
// false = no feed available
const TOKEN_PRICE_FEED = {
  'cBTC':   'BTC',
  'wcBTC':  'BTC',
  'WBTC.e': 'BTC',
  'ctUSD':  null,    // stablecoin
  'USDC.e': null,    // stablecoin
  'USDT.e': null,    // stablecoin
  'JUSD':   null,    // BTC-backed stablecoin, USD peg
}

const STABLECOIN_PRICE_USD = 1.0

const client = createPublicClient({
  chain: citrea,
  transport: http()
})

// ─── Fetch Prices from RedStone On-Chain Feeds ────────────────────────────────

async function fetchRedStonePrices() {
  try {
    const results = await Promise.all(
      Object.entries(PRICE_FEEDS).map(async ([symbol, address]) => {
        const [roundData, decimals] = await Promise.all([
          client.readContract({
            address,
            abi: AGGREGATOR_ABI,
            functionName: 'latestRoundData',
          }),
          client.readContract({
            address,
            abi: AGGREGATOR_ABI,
            functionName: 'decimals',
          }),
        ])

        const price     = Number(roundData[1]) / 10 ** decimals
        const updatedAt = Number(roundData[3])
        const age       = Math.floor(Date.now() / 1000) - updatedAt

        if (age > 7200) {
          console.warn(`⚠️  ${symbol} price is ${Math.floor(age / 60)} minutes old`)
        }

        return [symbol, price]
      })
    )

    return Object.fromEntries(results)

  } catch (error) {
    console.error(`⚠️  Could not fetch RedStone prices: ${error.message}`)
    return null
  }
}

// ─── Get USD price for a token symbol ────────────────────────────────────────

async function getTokenUSDPrice(symbol, cachedPrices = null) {
  const feedId = TOKEN_PRICE_FEED[symbol]

  // Stablecoin — hardcoded $1
  if (feedId === null) return STABLECOIN_PRICE_USD

  // No feed available for this token
  if (!feedId) return null

  const prices = cachedPrices || await fetchRedStonePrices()
  if (!prices) return null

  return prices[feedId] || null
}

// ─── Convert token amount to USD ─────────────────────────────────────────────

async function tokenAmountToUSD(amount, symbol, cachedPrices = null) {
  const price = await getTokenUSDPrice(symbol, cachedPrices)
  if (price === null) return null
  return amount * price
}

// ─── Format USD value ─────────────────────────────────────────────────────────

function formatUSD(amount) {
  if (amount === null || amount === undefined) return 'N/A'
  if (amount < 0.01)      return '<$0.01'
  if (amount < 1000)      return `$${amount.toFixed(2)}`
  if (amount < 1_000_000) return `$${(amount / 1000).toFixed(2)}K`
  return `$${(amount / 1_000_000).toFixed(2)}M`
}

export { fetchRedStonePrices, getTokenUSDPrice, tokenAmountToUSD, formatUSD }

export async function sendTelegram(message) {
  const token  = process.env.TELEGRAM_BOT_TOKEN
  const chatId = process.env.TELEGRAM_CHAT_ID

  if (!token || !chatId) {
    console.warn('⚠️  Telegram not configured — set TELEGRAM_BOT_TOKEN and TELEGRAM_CHAT_ID in .env')
    return
  }

  try {
    const res = await fetch(`https://api.telegram.org/bot${token}/sendMessage`, {
      method:  'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        chat_id:    chatId,
        text:       message,
        parse_mode: 'HTML',
      }),
    })

    if (!res.ok) {
      const err = await res.text()
      console.error('❌ Telegram error:', err)
    }
  } catch (err) {
    console.error('❌ Telegram send failed:', err.message)
  }
}
